CREATE OR REPLACE FUNCTION crop_batch_outbox() RETURNS trigger AS $$ DECLARE eid uuid:=gen_random_uuid();et text:=CASE WHEN TG_OP='INSERT' THEN 'CropBatchCreated' ELSE 'CropBatchUpdated' END;BEGIN INSERT INTO outbox_events(id,aggregate_type,aggregate_id,event_type,event_version,payload,status,created_at)VALUES(eid,'CropBatch',NEW.id::text,et,1,jsonb_build_object('eventId',eid,'eventType',et,'eventVersion',1,'aggregateType','CropBatch','aggregateId',NEW.id::text,'occurredAt',now(),'traceId',gen_random_uuid(),'producer','crop-service','routingKey','crop.batch.updated','payload',jsonb_build_object('batchId',NEW.id,'cropId',NEW.crop_id,'farmerId',NEW.farmer_id,'initialQuantity',NEW.initial_quantity,'availableQuantity',NEW.available_quantity,'reservedQuantity',NEW.reserved_quantity,'soldQuantity',NEW.sold_quantity,'province',NEW.province,'expiryDate',NEW.expiry_date,'status',NEW.status)),'PENDING',now());RETURN NEW;END$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_crop_batch_outbox AFTER INSERT OR UPDATE ON crop_batches FOR EACH ROW EXECUTE FUNCTION crop_batch_outbox();
